test('leaving the canvas discards a pending edge-hover frame', async ({ page }) => {
    const explorer = await openAliceGraph(page);
    const canvas = explorer.locator('svg.graph-canvas');
    const edge = explorer.locator('.edge', { has: page.locator('title', { hasText: 'Alice — knows → Bob' }) });
    const point = await besideEdge(page, 'Alice — knows → Bob', 0);

    await page.evaluate(() => {
        const nativeRequest = window.requestAnimationFrame.bind(window);
        const nativeCancel = window.cancelAnimationFrame.bind(window);
        const state = {
            holdNext: false,
            nextId: 1_000_000_000,
            callbacks: new Map(),
            flush() {
                const callbacks = [...this.callbacks.values()];
                this.callbacks.clear();
                callbacks.forEach((callback) => callback(performance.now()));
            },
        };
        const holdEdgeFrame = (event) => {
            if (!(event.target instanceof Element) || !event.target.closest('.edge')) return;
            state.holdNext = true;
            window.removeEventListener('pointermove', holdEdgeFrame, true);
        };
        window.addEventListener('pointermove', holdEdgeFrame, true);
        window.requestAnimationFrame = (callback) => {
            if (!state.holdNext) return nativeRequest(callback);
            state.holdNext = false;
            const id = state.nextId++;
            state.callbacks.set(id, callback);
            return id;
        };
        window.cancelAnimationFrame = (id) => {
            if (!state.callbacks.delete(id)) nativeCancel(id);
        };
        Object.defineProperty(window, '__heldEdgeHoverFrame', { value: state, configurable: true });
    });

    await page.mouse.move(point.x, point.y);
    expect(await page.evaluate(() => Reflect.get(window, '__heldEdgeHoverFrame').callbacks.size)).toBe(1);

    const bounds = await canvas.boundingBox();
    const viewport = await page.evaluate(() => ({ width: innerWidth, height: innerHeight }));
    const exit = [
        { x: bounds.x - 2, y: bounds.y + 10 },
        { x: bounds.x + bounds.width + 2, y: bounds.y + 10 },
        { x: bounds.x + 10, y: bounds.y - 2 },
        { x: bounds.x + 10, y: bounds.y + bounds.height + 2 },
    ].find((candidate) => candidate.x >= 1 && candidate.x < viewport.width - 1 &&
        candidate.y >= 1 && candidate.y < viewport.height - 1);
    expect(exit, 'the SVG has a reachable point outside its bounds').toBeDefined();
    await page.mouse.move(exit.x, exit.y);
    await expect(canvas).not.toHaveClass(/has-edge-hover/);

    await page.evaluate(() => Reflect.get(window, '__heldEdgeHoverFrame').flush());
    await expect(canvas).not.toHaveClass(/has-edge-hover/);
    await expect(edge).not.toHaveClass(/is-selected/);
});

